import{_ as p,a0 as l,w as o,s as r,ao as d,I as t,x as a,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"Sosreport：收集系統日誌和診斷信息的工具 | LCTT x X-CMD","titleTemplate":false,"description":"Sosreport：收集系統日誌和診斷信息的工具 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Sosreport：收集系統日誌和診斷信息的工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Sosreport：收集系統日誌和診斷信息的工具 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20180628 Sosreport - A Tool To Collect System Logs And Diagnostic Information","title":"Sosreport：收集系統日誌和診斷信息的工具","tag":"201807","desc":""},"relativePath":"201807/20180628 Sosreport - A Tool To Collect System Logs And Diagnostic Information.md","filePath":"[post].md"}'),c={name:"201807/20180628 Sosreport - A Tool To Collect System Logs And Diagnostic Information.md"};function h(g,s,u,k,b,f){const n=l("Link");return o(),r("div",null,[s[15]||(s[15]=d(`<h1 id="sosreport-收集系統日誌和診斷信息的工具" tabindex="-1">Sosreport：收集系統日誌和診斷信息的工具 <a class="header-anchor" href="#sosreport-收集系統日誌和診斷信息的工具" aria-label="Permalink to “Sosreport：收集系統日誌和診斷信息的工具”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/06/sos-720x340.png" alt=""></p><p>如果你是 RHEL 管理員，你可能肯定聽説過 <strong>Sosreport</strong> ：一個可擴展、可移植的支持數據收集工具。它是一個從類 Unix 操作系統中收集系統配置詳細信息和診斷信息的工具。當用户提出支持服務單時，他/她必須運行此工具並將由 Sosreport 工具生成的結果報告發送給 Red Hat 支持人員。然後，執行人員將根據報告進行初步分析，並嘗試找出系統中的問題。不僅在 RHEL 系統上，你可以在任何類 Unix 操作系統上使用它來收集系統日誌和其他調試信息。</p><h3 id="安裝-sosreport" tabindex="-1">安裝 Sosreport <a class="header-anchor" href="#安裝-sosreport" aria-label="Permalink to “安裝 Sosreport”">​</a></h3><p>Sosreport 在 Red Hat 官方系統倉庫中，因此你可以使用 Yum 或 DNF 包管理器安裝它，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install sos</span></span></code></pre></div><p>要麼，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install sos</span></span></code></pre></div><p>在 Debian、Ubuntu 和 Linux Mint 上運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install sosreport</span></span></code></pre></div><h3 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to “用法”">​</a></h3><p>安裝後，運行以下命令以收集系統配置詳細信息和其他診斷信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo sosreport</span></span></code></pre></div><p>系統將要求你輸入系統的一些詳細信息，例如系統名稱、案例 ID 等。相應地輸入詳細信息，然後按回車鍵生成報告。如果你不想更改任何內容並使用默認值，只需按回車鍵即可。</p><p>我的 CentOS 7 服務器的示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sosreport (version 3.5)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>This command will collect diagnostic and configuration information from</span></span>
<span class="line"><span>this CentOS Linux system and installed applications.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>An archive containing the collected information will be generated in</span></span>
<span class="line"><span>/var/tmp/sos.DiJXi7 and may be provided to a CentOS support</span></span>
<span class="line"><span>representative.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Any information provided to CentOS will be treated in accordance with</span></span>
<span class="line"><span>the published support policies at:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>https://wiki.centos.org/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The generated archive may contain data considered sensitive and its</span></span>
<span class="line"><span>content should be reviewed by the originating organization before being</span></span>
<span class="line"><span>passed to any third party.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>No changes will be made to system configuration.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Press ENTER to continue, or CTRL-C to quit.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Please enter your first initial and last name [server.ostechnix.local]:</span></span>
<span class="line"><span>Please enter the case id that you are generating this report for []:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Setting up archive ...</span></span>
<span class="line"><span>Setting up plugins ...</span></span>
<span class="line"><span>Running plugins. Please wait ...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Running 73/73: yum...</span></span>
<span class="line"><span>Creating compressed archive...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Your sosreport has been generated and saved in:</span></span>
<span class="line"><span>/var/tmp/sosreport-server.ostechnix.local-20180628171844.tar.xz</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The checksum is: 8f08f99a1702184ec13a497eff5ce334</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Please send this file to your support representative.</span></span></code></pre></div><p>如果你不希望系統提示你輸入此類詳細信息，請如下使用批處理模式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo sosreport --batch</span></span></code></pre></div><p>正如你在上面的輸出中所看到的，生成了一個歸檔報告並保存在 <code>/var/tmp/sos.DiJXi7</code> 中。在 RHEL 6/CentOS 6 中，報告將在 <code>/tmp</code> 中生成。你現在可以將此報告發送給你的支持人員，以便他可以進行初步分析並找出問題所在。</p><p>你可能會擔心或想知道報告中的內容。如果是這樣，你可以通過運行以下命令來查看它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo tar -tf /var/tmp/sosreport-server.ostechnix.local-20180628171844.tar.xz</span></span></code></pre></div><p>要麼，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vim /var/tmp/sosreport-server.ostechnix.local-20180628171844.tar.xz</span></span></code></pre></div><p>請注意，上述命令不會解壓存檔，而只顯示存檔中的文件和文件夾列表。如果要查看存檔中文件的實際內容，請首先使用以下命令解壓存檔：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo tar -xf /var/tmp/sosreport-server.ostechnix.local-20180628171844.tar.xz</span></span></code></pre></div><p>存檔的所有內容都將解壓當前工作目錄中 <code>ssosreport-server.ostechnix.local-20180628171844/</code> 目錄中。進入目錄並使用 <code>cat</code> 命令或任何其他文本瀏覽器查看文件內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd sosreport-server.ostechnix.local-20180628171844/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ cat uptime</span></span>
<span class="line"><span>17:19:02 up 1:03, 2 users, load average: 0.50, 0.17, 0.10</span></span></code></pre></div><p>有關 Sosreport 的更多詳細信息，請參閲手冊頁。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man sosreport</span></span></code></pre></div><p>就是這些了。希望這些有用。還有更多好東西。敬請關注！</p><p>乾杯！</p><hr>`,32)),t("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.ostechnix.com/sosreport-a-tool-to-collect-system-logs-and-diagnostic-information/"},{default:i(()=>[...s[0]||(s[0]=[a("https://www.ostechnix.com/sosreport-a-tool-to-collect-system-logs-and-diagnostic-information/",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://www.ostechnix.com/author/sk/"},{default:i(()=>[...s[2]||(s[2]=[a("SK",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const C=p(c,[["render",h]]);export{v as __pageData,C as default};
